package service_test

import (
	"testing"
	"time"

	"example.com/roombook/internal/service"
)

func TestOnHalfHour(t *testing.T) {
	// Arrange: two times on the boundary, and one between them.
	onTheHour := time.Date(2026, 10, 5, 14, 0, 0, 0, time.UTC)
	halfPast := time.Date(2026, 10, 5, 14, 30, 0, 0, time.UTC)
	between := time.Date(2026, 10, 5, 14, 10, 0, 0, time.UTC)

	// Act and assert: call the function and check what it returns.
	if !service.OnHalfHour(onTheHour) || !service.OnHalfHour(halfPast) {
		t.Error("OnHalfHour rejected a time on the hour or half hour")
	}
	if service.OnHalfHour(between) {
		t.Errorf("OnHalfHour(%v) = true, want false", between)
	}
}

package service_test

import (
	"errors"
	"slices"
	"testing"
	"time"

	"example.com/roombook/internal/domain"
	"example.com/roombook/internal/service"
	"example.com/roombook/internal/store/memory"
)

var now = time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)

var rooms = []domain.Room{
	{ID: 1, Name: "Turing", Building: "main-library", Capacity: 6, Amenities: []string{"whiteboard", "screen"}},
	{ID: 2, Name: "Lovelace", Building: "main-library", Capacity: 4, Amenities: []string{"whiteboard"}},
}

func at(s string) time.Time {
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		panic(err)
	}
	return t
}

func valid() domain.NewBooking {
	return domain.NewBooking{RoomID: 1, UserID: 1, StartsAt: at("2026-10-05T14:00:00Z"), EndsAt: at("2026-10-05T15:30:00Z"), Attendees: 3}
}

func newService() (*service.BookingService, *memory.BookingStore) {
	clock := func() time.Time { return now }
	store := memory.NewBookingStore(clock)
	return service.NewBookingService(store, memory.NewRoomStore(rooms), service.NoTx(store), clock), store
}

func TestCreateRejectsBrokenRules(t *testing.T) {
	tests := []struct {
		name  string
		edit  func(*domain.NewBooking)
		field string
	}{
		{"off the half hour", func(b *domain.NewBooking) { b.StartsAt = at("2026-10-05T14:10:00Z") }, "startsAt"},
		{"under 30 minutes", func(b *domain.NewBooking) { b.EndsAt = b.StartsAt }, "endsAt"},
		{"over 3 hours", func(b *domain.NewBooking) { b.EndsAt = at("2026-10-05T17:30:00Z") }, "endsAt"},
		{"in the past", func(b *domain.NewBooking) {
			b.StartsAt, b.EndsAt = at("2026-09-30T14:00:00Z"), at("2026-09-30T15:00:00Z")
		}, "startsAt"},
		{"over 14 days ahead", func(b *domain.NewBooking) {
			b.StartsAt, b.EndsAt = at("2026-10-16T14:00:00Z"), at("2026-10-16T15:00:00Z")
		}, "startsAt"},
		{"more people than seats", func(b *domain.NewBooking) { b.Attendees = 7 }, "attendees"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			svc, store := newService()
			in := valid()
			tt.edit(&in)

			_, err := svc.Create(t.Context(), in)

			var p *domain.ProblemError
			if !errors.As(err, &p) || p.Type != "validation-failed" {
				t.Fatalf("err = %v, want a validation-failed problem", err)
			}
			if !slices.ContainsFunc(p.Fields, func(f domain.FieldError) bool { return f.Field == tt.field }) {
				t.Errorf("fields %v don't name %s", p.Fields, tt.field)
			}
			if n, _ := store.CountUpcoming(t.Context(), 1, now); n != 0 {
				t.Errorf("saved %d bookings that break a rule", n)
			}
		})
	}
}

