package service_test

import (
	"context"
	"testing"
	"time"

	"example.com/roombook/internal/domain"
	"example.com/roombook/internal/service"
	"example.com/roombook/internal/store/memory"
)

// spyStore records what the service asks of it, in place of a mocking library.
type spyStore struct {
	countedAt []time.Time
	inserted  []domain.NewBooking
}

func (s *spyStore) Get(context.Context, int64) (domain.Booking, error) {
	return domain.Booking{}, domain.ErrNotFound
}

func (s *spyStore) CountUpcoming(_ context.Context, _ int64, at time.Time) (int, error) {
	s.countedAt = append(s.countedAt, at)
	return 0, nil
}

func (s *spyStore) Insert(_ context.Context, b domain.NewBooking) (domain.Booking, error) {
	s.inserted = append(s.inserted, b)
	return domain.Booking{NewBooking: b, ID: 1001, Status: domain.Confirmed, Version: 1}, nil
}

func TestCreateChecksTheLimitAtTheClocksTimeThenSaves(t *testing.T) {
	spy := &spyStore{}
	svc := service.NewBookingService(spy, memory.NewRoomStore(rooms), service.NoTx(spy), func() time.Time { return now })

	if _, err := svc.Create(t.Context(), valid()); err != nil {
		t.Fatal(err)
	}

	if len(spy.countedAt) != 1 || !spy.countedAt[0].Equal(now) {
		t.Errorf("CountUpcoming called at %v, want once at %v", spy.countedAt, now)
	}
	if len(spy.inserted) != 1 || spy.inserted[0] != valid() {
		t.Errorf("Insert called with %+v, want once with %+v", spy.inserted, valid())
	}
}

package api_test

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"example.com/roombook/internal/api"
	"example.com/roombook/internal/auth"
	"example.com/roombook/internal/domain"
	"example.com/roombook/internal/service"
	"example.com/roombook/internal/store/memory"
)

var now = time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)

var tokens = auth.NewAccessTokens([]byte("test-secret-that-is-at-least-32-bytes"))

var rooms = []domain.Room{
	{ID: 1, Name: "Turing", Building: "main-library", Capacity: 6, Amenities: []string{"whiteboard", "screen"}},
	{ID: 2, Name: "Lovelace", Building: "main-library", Capacity: 4, Amenities: []string{"whiteboard"}},
}

// newAPI returns the real handler, with in-memory stores and a fixed clock.
func newAPI() http.Handler {
	clock := func() time.Time { return now }
	roomStore := memory.NewRoomStore(rooms)
	bookingStore := memory.NewBookingStore(clock)
	return api.New(api.Deps{
		Rooms:    roomStore,
		Bookings: service.NewBookingService(bookingStore, roomStore, service.NoTx(bookingStore), clock),
		Users:    auth.NewUsers(),
		Tokens:   tokens,
	}).Handler()
}

// bearer signs a token for a user, the way the app signs tokens.
func bearer(t *testing.T, userID int64, role string) string {
	t.Helper()
	token, err := tokens.Issue(userID, role, nil, auth.RoleScopes[role])
	if err != nil {
		t.Fatal(err)
	}
	return "Bearer " + token
}

// do sends one request straight to the handler: no server, no port, no network.
func do(h http.Handler, method, path, auth, body string) *httptest.ResponseRecorder {
	req := httptest.NewRequest(method, path, strings.NewReader(body))
	req.Header.Set("Content-Type", "application/json")
	if auth != "" {
		req.Header.Set("Authorization", auth)
	}
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec
}

func decode(t *testing.T, rec *httptest.ResponseRecorder) map[string]any {
	t.Helper()
	var v map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &v); err != nil {
		t.Fatalf("body isn't JSON: %v\n%s", err, rec.Body)
	}
	return v
}

func fmtValue(v any) string { return fmt.Sprint(v) }

package api_test

import (
	"net/http"
	"testing"
)

const booking = `{"roomId": 1, "startsAt": "2026-10-05T14:00:00Z", "endsAt": "2026-10-05T15:30:00Z", "attendees": 3}`

const ada = 1 // Ada's user id

func TestCreateBookingSaysWhereItLives(t *testing.T) {
	rec := do(newAPI(), "POST", "/v1/bookings", bearer(t, ada, "member"), booking)

	if rec.Code != http.StatusCreated {
		t.Fatalf("status = %d, want 201\n%s", rec.Code, rec.Body)
	}
	if got := rec.Header().Get("Location"); got != "/v1/bookings/1001" {
		t.Errorf("Location = %q", got)
	}
	if body := decode(t, rec); body["status"] != "confirmed" || body["startsAt"] != "2026-10-05T14:00:00Z" {
		t.Errorf("body = %v", body)
	}
}

func TestCreateBookingWithoutATokenIs401(t *testing.T) {
	rec := do(newAPI(), "POST", "/v1/bookings", "", booking)

	if rec.Code != http.StatusUnauthorized || rec.Header().Get("WWW-Authenticate") != `Bearer realm="roombook"` {
		t.Fatalf("status = %d, WWW-Authenticate = %q", rec.Code, rec.Header().Get("WWW-Authenticate"))
	}
	if ct := rec.Header().Get("Content-Type"); ct != "application/problem+json" {
		t.Errorf("Content-Type = %q", ct)
	}
}

func TestCreateBookingReportsEveryInvalidField(t *testing.T) {
	body := `{"roomId": 1, "startsAt": "2026-10-05T14:10:00Z", "endsAt": "2026-10-05T15:30:00Z", "attendees": 9}`

	rec := do(newAPI(), "POST", "/v1/bookings", bearer(t, ada, "member"), body)

	if rec.Code != http.StatusUnprocessableEntity {
		t.Fatalf("status = %d, want 422", rec.Code)
	}
	want := `[map[field:startsAt message:must be on the hour or half past] map[field:attendees message:Turing holds at most 6 people]]`
	if got := fmtValue(decode(t, rec)["errors"]); got != want {
		t.Errorf("errors =\n%s\nwant\n%s", got, want)
	}
}

func TestCreateBookingTwiceIs409(t *testing.T) {
	h := newAPI()
	auth := bearer(t, ada, "member")
	do(h, "POST", "/v1/bookings", auth, booking)

	rec := do(h, "POST", "/v1/bookings", auth, booking)

	if rec.Code != http.StatusConflict || decode(t, rec)["type"] != "https://roombook.example/problems/booking-overlap" {
		t.Fatalf("status = %d\n%s", rec.Code, rec.Body)
	}
}

func TestCreateBookingWithBrokenJSONIs400(t *testing.T) {
	rec := do(newAPI(), "POST", "/v1/bookings", bearer(t, ada, "member"), `{"roomId": 1,`)

	if rec.Code != http.StatusBadRequest || decode(t, rec)["type"] != "https://roombook.example/problems/invalid-json" {
		t.Fatalf("status = %d\n%s", rec.Code, rec.Body)
	}
}

package postgres_test

import (
	_ "embed"
	"errors"
	"net/url"
	"os"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"

	"example.com/roombook/db"
	"example.com/roombook/internal/domain"
	"example.com/roombook/internal/store/postgres"
)

var migrateOnce sync.Once

// fixtures are the buildings, users, and rooms every test expects.
//
//go:embed testdata/seed.sql
var fixtures []byte

// testPool connects to TEST_DATABASE_URL, runs the migrations and loads the fixtures
// once per run, and empties bookings, so every test starts from the fixtures alone.
func testPool(t *testing.T) *pgxpool.Pool {
	t.Helper()
	if testing.Short() {
		t.Skip("integration test: needs TEST_DATABASE_URL")
	}
	dsn := os.Getenv("TEST_DATABASE_URL")
	if u, err := url.Parse(dsn); err != nil || !strings.HasSuffix(u.Path, "_test") {
		t.Skip("set TEST_DATABASE_URL to a database whose name ends in _test")
	}
	pool, err := pgxpool.New(t.Context(), dsn)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(pool.Close)
	migrateOnce.Do(func() {
		if err := db.Migrate(t.Context(), pool); err != nil {
			t.Fatalf("migrate: %v", err)
		}
		if _, err := pool.Exec(t.Context(), "TRUNCATE buildings, users, rooms, bookings RESTART IDENTITY CASCADE"); err != nil {
			t.Fatal(err)
		}
		if _, err := pool.Exec(t.Context(), string(fixtures)); err != nil {
			t.Fatalf("load fixtures: %v", err)
		}
	})
	if _, err := pool.Exec(t.Context(), "TRUNCATE bookings RESTART IDENTITY"); err != nil {
		t.Fatal(err)
	}
	return pool
}

func TestInsertOverlapIsABookingOverlap(t *testing.T) {
	store := postgres.NewBookingStore(testPool(t))
	if _, err := store.Insert(t.Context(), at("2026-10-05T14:00:00Z", "2026-10-05T15:30:00Z")); err != nil {
		t.Fatal(err)
	}

	_, err := store.Insert(t.Context(), at("2026-10-05T15:00:00Z", "2026-10-05T16:00:00Z"))

	var p *domain.ProblemError
	if !errors.As(err, &p) || p.Type != "booking-overlap" {
		t.Fatalf("err = %v, want a booking-overlap problem", err)
	}
}

