package api_test

import (
	"bytes"
	"io"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/getkin/kin-openapi/openapi3filter"
	"github.com/getkin/kin-openapi/routers/gorillamux"

	"example.com/roombook/openapi"
)

// TestResponsesMatchTheSpec sends real requests to the handler and checks every
// response against openapi.yaml: status codes, headers, and body schemas.
func TestResponsesMatchTheSpec(t *testing.T) {
	doc, _, err := openapi.Load(t.Context())
	if err != nil {
		t.Fatal(err)
	}
	doc.Servers = nil // match paths alone, whatever the host
	router, err := gorillamux.NewRouter(doc)
	if err != nil {
		t.Fatal(err)
	}
	h := newAPI()
	auth := bearer(t, ada, "member")

	cases := []struct{ method, path, auth, body string }{
		{"GET", "/v1/rooms", "", ""},
		{"GET", "/v1/rooms/1", "", ""},
		{"GET", "/v1/rooms/99", "", ""},
		{"POST", "/v1/bookings", auth, booking},
		{"POST", "/v1/bookings", auth, booking},
		{"POST", "/v1/bookings", "", booking},
		{"GET", "/v1/bookings/1001", auth, ""},
	}
	for _, c := range cases {
		req := httptest.NewRequest(c.method, c.path, strings.NewReader(c.body))
		req.Header.Set("Content-Type", "application/json")
		if c.auth != "" {
			req.Header.Set("Authorization", c.auth)
		}
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, req)

		route, params, err := router.FindRoute(req)
		if err != nil {
			t.Fatalf("%s %s isn't in the spec: %v", c.method, c.path, err)
		}
		input := &openapi3filter.ResponseValidationInput{
			RequestValidationInput: &openapi3filter.RequestValidationInput{
				Request: req, PathParams: params, Route: route,
				Options: &openapi3filter.Options{AuthenticationFunc: openapi3filter.NoopAuthenticationFunc},
			},
			Status: rec.Code,
			Header: rec.Header(),
			Body:   io.NopCloser(bytes.NewReader(rec.Body.Bytes())),
		}
		if err := openapi3filter.ValidateResponse(t.Context(), input); err != nil {
			t.Errorf("%s %s answered %d, which the spec doesn't allow:\n%v", c.method, c.path, rec.Code, err)
		}
	}
}

